'@
$archiveBytes = [Convert]::FromBase64String($archiveBase64)
$hashAlgorithm = [System.Security.Cryptography.SHA256]::Create()
try {
    $actualHash = ([BitConverter]::ToString($hashAlgorithm.ComputeHash($archiveBytes))).Replace('-', '').ToLowerInvariant()
} finally {
    $hashAlgorithm.Dispose()
}
if ($actualHash -ne '3099bcc890bfa7eb583797821ac1b8c21a5f17168dca63ead0d4d48a9aa39a23') {
    throw 'The embedded archive is damaged. Copy the complete script again.'
}
$restoreRoot = [System.IO.Path]::GetFullPath($DestinationPath)
$skillPath = Join-Path $restoreRoot 'infopath-to-angular'
if (Test-Path -LiteralPath $skillPath) {
    throw "The output folder already exists: $skillPath. Choose another DestinationPath. No files were overwritten."
}
$rootPrefix = $restoreRoot.TrimEnd([char[]]@('\', '/')) + [System.IO.Path]::DirectorySeparatorChar
Add-Type -AssemblyName System.IO.Compression
$archiveStream = New-Object System.IO.MemoryStream
$archive = $null
try {
    $archiveStream.Write($archiveBytes, 0, $archiveBytes.Length)
    $archiveStream.Position = 0
    $archive = New-Object System.IO.Compression.ZipArchive($archiveStream, [System.IO.Compression.ZipArchiveMode]::Read, $false)
    if ($archive.Entries.Count -ne 13) { throw 'Unexpected archive file count.' }
    # Check every path before creating any output files.
    foreach ($entry in $archive.Entries) {
        if (-not $entry.FullName.StartsWith('infopath-to-angular/', [StringComparison]::Ordinal)) {
            throw "Unexpected archive entry: $($entry.FullName)"
        }
        $entryPath = [System.IO.Path]::GetFullPath((Join-Path $restoreRoot $entry.FullName))
        if (-not $entryPath.StartsWith($rootPrefix, [StringComparison]::OrdinalIgnoreCase)) {
            throw "Archive entry is outside the destination: $($entry.FullName)"
        }
    }
    foreach ($entry in $archive.Entries) {
        $entryPath = [System.IO.Path]::GetFullPath((Join-Path $restoreRoot $entry.FullName))
        [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($entryPath)) | Out-Null
        $inputStream = $entry.Open()
        $outputStream = $null
        try {
            $outputStream = [System.IO.File]::Open($entryPath, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write)
            $inputStream.CopyTo($outputStream)
        } finally {
            if ($null -ne $outputStream) { $outputStream.Dispose() }
            $inputStream.Dispose()
        }
    }
} finally {
    if ($null -ne $archive) { $archive.Dispose() }
    $archiveStream.Dispose()
}
Write-Output "Restored 13 files to: $skillPath"
Write-Output "Start with: $(Join-Path $skillPath 'README.md')"
